import java.util.*;
class Solution {
    public int maxEnvelopes(int[][] envelopes) {
        Arrays.sort(envelopes, (a, b) -> a[0] != b[0] ? a[0] - b[0] : b[1] - a[1]);
        int[] dp = new int[envelopes.length];
        int size = 0;
        for (int[] env : envelopes) {
            int h = env[1];
            int l = 0, r = size;
            while (l < r) {
                int m = l + (r - l) / 2;
                if (dp[m] < h) l = m + 1;
                else r = m;
            }
            dp[l] = h;
            if (l == size) size++;
        }
        return size;
    }
}

